  <script type="module">

    /* ===== 暂存变更 ===== */
    var pendingDeltas = {};
    var pendingTexts = {};

    function markDirty() {
      $('#save-btn').show();
    }

    function addDelta(path, delta) {
      pendingDeltas[path] = (pendingDeltas[path] || 0) + delta;
      markDirty();
    }

    function addText(path, value) {
      pendingTexts[path] = value;
      markDirty();
    }

    /* ===== 批量保存 ===== */
    async function saveAll() {
      var messageId = getCurrentMessageId();
      var mvuData = Mvu.getMvuData({ type: 'message', message_id: messageId });

      var paths = Object.keys(pendingDeltas);
      for (var i = 0; i < paths.length; i++) {
        var p = paths[i];
        var d = pendingDeltas[p];
        _.update(mvuData, 'stat_data.' + p, function(v) { return (v || 0) + d; });
      }

      var tPaths = Object.keys(pendingTexts);
      for (var j = 0; j < tPaths.length; j++) {
        var tp = tPaths[j];
        _.set(mvuData, 'stat_data.' + tp, pendingTexts[tp]);
      }

      await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: messageId });

      pendingDeltas = {};
      pendingTexts = {};
      $('#save-btn').hide();

      populateCharacterData();
    }

    /* ===== 显示刷新 ===== */
    function populateCharacterData() {
      var all = getAllVariables();

      var dateVal = _.get(all, 'stat_data.全局.日期', '—');
      var timeVal = _.get(all, 'stat_data.全局.时间', '—');
      var locVal = _.get(all, 'stat_data.全局.地点', '—');
      $('#g-date').text(dateVal).attr('data-path', '日期');
      $('#g-time').text(timeVal).attr('data-path', '时间');
      $('#g-loc').text(locVal).attr('data-path', '地点');

      $('#p-bal').text(_.get(all, 'stat_data.主角.余额', 0));
      $('#p-ord').text(_.get(all, 'stat_data.主角.总点单次数', 0));

      var site = _.get(all, 'stat_data.网站', {});
      var $siteList = $('#site-list');
      $siteList.empty();
      var siteEntries = Object.entries(site);
      if (siteEntries.length === 0) {
        $siteList.append('<div class="empty-hint">暂无记录</div>');
      } else {
        siteEntries.forEach(function (pair) {
          var name = pair[0];
          var data = pair[1];
          var count = _.get(data, '被点单次数', 0);
          var favor = _.get(data, '好感度', 50);
          var pct = Math.min(Math.max(favor, 0), 100);

          $siteList.append(
            '<div class="site-entry">' +
              '<div class="site-top">' +
                '<span class="sn">' + name + '</span>' +
                '<div class="site-count-ctrl">' +
                  '<span class="site-num-btn btn-site-count-minus" data-name="' + name + '">−</span>' +
                  '<span class="sc site-count-val" data-name="' + name + '">×' + count + '</span>' +
                  '<span class="site-num-btn btn-site-count-plus" data-name="' + name + '">+</span>' +
                '</div>' +
              '</div>' +
              '<div class="site-favor">' +
                '<span class="favor-label">好感</span>' +
                '<span class="site-num-btn btn-site-favor-minus" data-name="' + name + '">−</span>' +
                '<div class="favor-bar-bg">' +
                  '<div class="favor-bar-fill site-favor-bar" data-name="' + name + '" style="width:' + pct + '%"></div>' +
                '</div>' +
                '<span class="favor-val site-favor-val" data-name="' + name + '">' + favor + '</span>' +
                '<span class="site-num-btn btn-site-favor-plus" data-name="' + name + '">+</span>' +
              '</div>' +
            '</div>'
          );
        });
      }

      var tasks = _.get(all, 'stat_data.任务栏', {});
      var $taskList = $('#task-list');
      $taskList.empty();
      var taskEntries = Object.entries(tasks);
      if (taskEntries.length === 0) {
        $taskList.append('<div class="empty-hint">暂无任务</div>');
      } else {
        taskEntries.forEach(function (pair) {
          var tName = pair[0];
          var tData = pair[1];
          var desc = _.get(tData, '描述', '');
          var diff = _.get(tData, '难度', '普通');
          var reward = _.get(tData, '奖励', 0);

          var diffClass = 'd-normal';
          if (diff === '简单') diffClass = 'd-simple';
          if (diff === '困难') diffClass = 'd-hard';

          $taskList.append(
            '<div class="task-card">' +
              '<div class="task-name">' + tName + '</div>' +
              '<div class="task-desc">' + desc + '</div>' +
              '<div class="task-footer">' +
                '<span class="task-diff ' + diffClass + '">' + diff + '</span>' +
                '<span class="task-reward">+' + reward + '</span>' +
              '</div>' +
            '</div>'
          );
        });
      }
    }

    /* ===== 文本编辑交互 ===== */
    function startEditGlobal($el) {
      var path = $el.data('path');
      var currentVal = $el.text();
      var $input = $('<input class="gv-edit" type="text">').val(currentVal);
      $el.replaceWith($input);
      $input.focus().select();

      function commitEdit() {
        var newVal = $input.val().trim();
        if (newVal === '') { newVal = currentVal; }
        var $newSpan = $('<span class="gv" data-path="' + path + '">' + newVal + '</span>');
        $input.replaceWith($newSpan);
        if (newVal !== currentVal) {
          addText('全局.' + path, newVal);
          if (path === '日期') { $newSpan.attr('id', 'g-date'); }
          if (path === '时间') { $newSpan.attr('id', 'g-time'); }
          if (path === '地点') { $newSpan.attr('id', 'g-loc'); }
        }
      }

      $input.on('blur', commitEdit);
      $input.on('keydown', function(e) {
        if (e.key === 'Enter') { $input.blur(); }
        if (e.key === 'Escape') {
          $input.val(currentVal);
          $input.blur();
        }
      });
    }

    /* ===== 本地预览更新工具函数 ===== */
    function updateNumDisplay($el, delta, prefix) {
      var text = $el.text();
      var current;
      if (prefix) {
        current = parseInt(text.replace(prefix, '')) || 0;
        $el.text(prefix + (current + delta));
      } else {
        current = parseInt(text) || 0;
        $el.text(current + delta);
      }
      return current + delta;
    }

    /* ===== 点单逻辑 ===== */

    function getOrderFormData() {
      return {
        姓名: $('#ord-name').val().trim(),
        性别: $('#ord-gender').val().trim(),
        年龄: $('#ord-age').val().trim(),
        外貌: $('#ord-appearance').val().trim(),
        职业: $('#ord-job').val().trim(),
        性癖: $('#ord-fetish').val().trim()
      };
    }

    function toYaml(data) {
      var yaml = '角色信息:\n';
      var entries = Object.entries(data);
      for (var i = 0; i < entries.length; i++) {
        var key = entries[i][0];
        var value = entries[i][1];
        if (!value) { continue; }
        if (value.indexOf('\n') !== -1) {
          yaml += '  ' + key + ': |\n';
          var lines = value.split('\n');
          for (var j = 0; j < lines.length; j++) {
            yaml += '    ' + lines[j] + '\n';
          }
        } else {
          yaml += '  ' + key + ': ' + value + '\n';
        }
      }
      return yaml;
    }

    function sendToChatBox(text) {
      try {
        var textarea = parent.document.querySelector('#send_textarea');
        if (textarea) {
          var currentVal = textarea.value;
          if (currentVal.trim() !== '') {
            if (currentVal.indexOf(text) === -1) {
              textarea.value = currentVal + '\n' + text;
            }
          } else {
            textarea.value = text;
          }
          textarea.dispatchEvent(new Event('input', { bubbles: true }));
          textarea.focus();
        } else {
          if (typeof parent.triggerQuickReply === 'function') {
            parent.triggerQuickReply(text);
          }
        }
      } catch (e) {
        console.error('sendToChatBox error:', e);
      }
    }

    async function addEntryToWorldbook(name, yamlContent) {
      try {
        var getWB = parent.getCharWorldbookNames || window.getCharWorldbookNames;
        var createWB = parent.createWorldbookEntries || window.createWorldbookEntries;

        if (!getWB || !createWB) {
          console.warn('世界书API不可用');
          return false;
        }

        var charWorldbooks = getWB('current');
        var targetWorldbook = charWorldbooks.primary;

        if (!targetWorldbook) {
          if (parent.toastr) parent.toastr.warning('当前角色没有绑定主世界书！');
          return false;
        }

        var newEntry = {
          name: name,
          content: yamlContent,
          strategy: {
            type: 'selective',
            keys: [name]
          },
          position: {
            type: 'before_character_definition'
          },
          recursion: {
            prevent_incoming: true,
            prevent_outgoing: true
          }
        };

        await createWB(targetWorldbook, [newEntry]);
        if (parent.toastr) parent.toastr.success('已将【' + name + '】录入世界书');
        return true;
      } catch (e) {
        console.error('addEntryToWorldbook error:', e);
        if (parent.toastr) parent.toastr.error('录入世界书失败');
        return false;
      }
    }

    function setOrderStatus(msg, type) {
