      var data = getOrderFormData();

      if (!data.姓名) {
        setOrderStatus('姓名不能为空', 's-err');
        $('#ord-name').focus();
        return;
      }

      var $btn = $('#order-confirm-btn');
      $btn.prop('disabled', true);
      setOrderStatus('PROCESSING...', '');

      var yamlStr = toYaml(data);
      var sendText = '已点单' + data.姓名;

      sendToChatBox(sendText);

      var wbResult = await addEntryToWorldbook(data.姓名, yamlStr);

      if (wbResult) {
        setOrderStatus('CONFIRMED — ' + data.姓名, 's-ok');
      } else {
        setOrderStatus('已发送至输入框', 's-ok');
      }

      $btn.prop('disabled', false);
    }

