export const Schema = z.object({
  全局: z.object({
    日期: z.string().prefault('待初始化'),
    时间: z.string().prefault('待初始化'),
    地点: z.string().prefault('待初始化'),
  }).prefault({}),

  主角: z.object({
    余额: z.coerce.number().transform(v => Math.max(v, 0)).prefault(0),
    总点单次数: z.coerce.number().transform(v => Math.max(v, 0)).prefault(0),
  }).prefault({}),

  网站: z.record(
    z.string().describe('角色名'),
    z.object({
      被点单次数: z.coerce.number().transform(v => Math.max(v, 0)).prefault(0),
      好感度: z.coerce.number().transform(v => _.clamp(v, 0, 100)).prefault(50),
    }).prefault({}),
  ).prefault({}),

  任务栏: z.record(
    z.string().describe('任务名'),
    z.object({
      描述: z.string().prefault('待初始化'),
      难度: z.enum(['简单', '普通', '困难']).prefault('普通'),
      奖励: z.coerce.number().transform(v => Math.max(v, 0)).prefault(0),
    }).prefault({}),
  ).transform(data => {
    return _(data).entries().takeRight(3).fromPairs().value();
  }).prefault({}),
});

$(() => {
  registerMvuSchema(Schema);
})
